object Solution { def maximumGap(nums: Array[Int]): Int = { if (nums.length < 2) return 0; val low = nums.min; val high = nums.max; if (low == high) return 0; val size = math.max(1, (high - low) / (nums.length - 1)); val count = (high - low) / size + 1; val mins = Array.fill(count)(Int.MaxValue); val maxs = Array.fill(count)(Int.MinValue); val used = Array.fill(count)(false); for (n <- nums) { val i = (n - low) / size; used(i) = true; mins(i) = math.min(mins(i), n); maxs(i) = math.max(maxs(i), n) }; var best = 0; var previous = low; for (i <- 0 until count if used(i)) { best = math.max(best, mins(i) - previous); previous = maxs(i) }; best } }